let ctx,enabled=localStorage.getItem('mq.sound')!=='off';
export function soundEnabled(){return enabled;}
export function toggleSound(){enabled=!enabled;localStorage.setItem('mq.sound',enabled?'on':'off');if(enabled){unlockAudio();playSound('correct');}return enabled;}
export function unlockAudio(){if(!enabled)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;ctx||=new AC();if(ctx.state==='suspended')ctx.resume().catch(()=>{});}catch{}}
export function playSound(type){if(!enabled||!ctx||ctx.state!=='running')return;const notes={correct:[523,659,784],wrong:[330,247],timeout:[294,220],finish:[392,523,659,784,1047],start:[392,523,659],click:[660]}[type];if(!notes)return;const now=ctx.currentTime;notes.forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=now+i*.095;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.07,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+.17);o.connect(g).connect(ctx.destination);o.start(t);o.stop(t+.18);});}
export function confetti(parent){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.createElement('div');box.className='mq-confetti';box.setAttribute('aria-hidden','true');for(let i=0;i<30;i++){const p=document.createElement('i');p.style.setProperty('--x',((i*37)%100)+'%');p.style.setProperty('--delay',(i%7)*.045+'s');p.style.setProperty('--spin',((i%2?1:-1)*(120+i*11))+'deg');p.style.background=['#f8d64d','#ff6685','#65b6ff','#6ee5a3'][i%4];box.append(p);}parent.append(box);setTimeout(()=>box.remove(),1500);}
